//! Raw FFI to the camera's SigmaStar MI user libraries, generated by `build.rs` from our declarations in `mi.h`; the
//! layout they must keep is checked by `layout`. Every item is `unsafe` to use; the `mi` crate wraps it.
#![no_std]
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code)]
#![allow(clippy::all)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

#[cfg(target_arch = "arm")]
mod layout;

/// Linux UAPI for the UVC gadget: V4L2 and `g_uvc` structs and constants (ARM layout).
pub mod uapi {
    #![allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code)]
    #![allow(clippy::all)]
    include!(concat!(env!("OUT_DIR"), "/uapi.rs"));
}
